function convolve(samples, ir){
  var n=samples.length, m=ir.length, out=new Float32Array(n+m-1);
  for(var i=0;i<n;i++){ var x=samples[i]; for(var j=0;j<m;j++){ out[i+j]+=x*ir[j]; } }
  var peak=0; for(var k=0;k<out.length;k++){ if(Math.abs(out[k])>peak) peak=Math.abs(out[k]); }
  if(peak>1.0001){ for(var p=0;p<out.length;p++) out[p]/=peak; }
  return out;
}
function makeIR(decay, len, rng){
  var a=new Float32Array(len); a[0]=1;
  for(var i=1;i<len;i++){ a[i]=Math.pow(decay, i) * (rng? (0.6+rng()*0.4):1); }
  return a;
}
